"""Differential test with large control arrays (L=8, M=16, R up to 64)."""
import json, random, sys
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/dev')
import ref as refmod
from adapter import execute_batch

def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    for seed in range(lo, hi):
        rng = random.Random(seed)
        M, L = rng.choice([(16, 8), (16, 1), (8, 8), (13, 5), (2, 8)]), None
        L = rng.choice([1, 2, 8])
        U = rng.choice([1 << 8, 1 << 16, 2147483647])
        R = rng.choice([1, 2, 17, 40, 64])
        borders = [0] + sorted(rng.sample(range(1, U), min(R, U - 1))) + [U] if U > 1 else [0, U]
        kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
        flows = list(range(rng.randint(1, 6)))
        if kind == 'sp':
            policy = {'kind': 'sp', 'levels': [[f, rng.randrange(U)] for f in flows]}
        elif kind == 'wfq':
            policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 1024)] for f in flows]}
        else:
            policy = {'kind': kind}
        ev, nid, saved = [], 0, []
        for _ in range(rng.randint(20, 260)):
            pick = rng.random()
            if pick < 0.4:
                ev.append(['enqueue', nid, rng.choice(flows), rng.randint(1, 300), rng.randrange(U)]); nid += 1
            elif pick < 0.55:
                ev.append(['dequeue', rng.randint(1, 25)])
            elif pick < 0.70:
                ev.append(['sample'])
            elif pick < 0.78:
                k = rng.randint(2, min(64, U - 1)) if U > 2 else 1
                nb = [0] + sorted(rng.sample(range(1, U), min(k, U - 1))) + [U] if U > 1 else [0, U]
                ev.append(['repartition', nb])
            elif pick < 0.84:
                ev.append(['cancel', rng.randrange(0, nid + 3)])
            elif pick < 0.9:
                ev.append(['inspect', rng.randrange(0, nid + 3)])
            elif pick < 0.95:
                name = rng.randrange(6); ev.append(['save', name]); saved.append(name)
            elif saved:
                ev.append(['restore', rng.choice(saved)])
        spec = {'banks': M, 'load_balancers': L,
                'fifo_bytes': rng.choice([1, 500, 10 ** 6]),
                'pifo_bytes': rng.choice([1, 300, 10 ** 6]),
                'refill_batch': rng.choice([1, 3, 32]),
                'sample_period': rng.choice([1, 2, 9, 100000]),
                'borders': borders, 'policy': policy, 'events': ev}
        request = {'runs': [spec]}
        mine = json.loads(json.dumps(execute_batch(request)))
        theirs = json.loads(json.dumps(refmod.run_batch(request)))
        if mine != theirs:
            print('SEED', seed, 'MISMATCH'); json.dump(request, open('/workspace/dev/fail4_%d.json' % seed, 'w'))
            a, b = mine['runs'][0], theirs['runs'][0]
            for j in range(min(len(a['log']), len(b['log']))):
                if a['log'][j] != b['log'][j]:
                    print(' row', j, a['log'][j], b['log'][j]); break
            else:
                print(' state A', json.dumps(a['state'])[:900]); print(' state B', json.dumps(b['state'])[:900])
            return 1
    print('checked', hi - lo, 'large-control batches')
    return 0

sys.exit(main())
